use super::*;
fn report(name:&str,ops:&[Op]){let(mut d,mut n,mut w)=(0i32,0u64,0f64);for o in ops{match o.kind{OperationType::PushCondition=>d+=1,OperationType::PopCondition=>{d-=1;assert!(d>=0);},OperationType::CCX|OperationType::CCZ=>{n+=1;w+=2f64.powi(-d-i32::from(o.c_condition!=NO_BIT));},_=>{}}}assert_eq!(d,0);let(q,b,_,_)=analyze_ops(ops.iter());eprintln!("POLY_STAGE name={name} ops={} nq={q} nb={b} native={n} depth_weight={w:.6} diagnostic_only=1",ops.len());}
#[test]#[ignore]fn frozen_stream_only_after_native_controls(){let input=std::env::var("TRUTH_AUDIT_INPUT").unwrap();let prefix=std::env::var("TRUTH_AUDIT_OUTPUT").unwrap();let mut ops=super::super::break_profile::load_ops(&input);report("input",&ops);ops=simplify(ops);report("identities",&ops);ops=witnesses(ops);report("witnesses",&ops);super::super::break_profile::save_ops(&format!("{prefix}-poly.ops.bin"),&ops);}
